"""Real HTTP/Chromium consultation availability and staff lifecycle. No mail or provider."""
import json,time
import requests
from playwright.sync_api import expect
from release_cases import db
from staff_cases import OWNER,STAFF

def run_browser(env,browser):
    globals().update({k:env[k] for k in ['ROOT','WEB','BASE','QA','check','soup','token','form_data','submit']})
    db('DELETE FROM ci_rate_limits');root=BASE+'/existing/admin/index.php';public=BASE+'/existing/index.php?page=consultation';settings=root+'?view=consultation-settings'
    check('Fresh scheduling is prepared but empty and disabled',db("SELECT value FROM fresh_settings WHERE name='appointments_schema_version'")==[{'value':'1'}] and db('SELECT enabled,rules FROM fresh_appointment_settings')==[{'enabled':0,'rules':'[]'}] and not db('SELECT * FROM fresh_appointments'))
    check('Unprepared consultation form keeps preference workflow',soup(requests.get(public)).select_one('[name=preferred_date]') is not None and 'does not reserve a calendar slot' in requests.get(public).text)
    owner=requests.Session();submit(owner,root+'?view=login','login',{'email':'owner@example.invalid','password':OWNER})
    r=submit(owner,settings,'appointments_setup',{'current_password':OWNER,'csrf':'invalid'});check('Scheduling setup rejects CSRF','session expired' in r.text.lower() and not db("SELECT value FROM ci_settings WHERE name='appointments_schema_version'"))
    r=submit(owner,settings,'appointments_setup',{'current_password':'wrong'});check('Scheduling setup checks owner password','current password' in r.text.lower())
    r=submit(owner,settings,'appointments_setup',{'current_password':OWNER});check('Owner prepares disabled calendar without appointments','Studio availability' in r.text and db('SELECT enabled FROM ci_appointment_settings')==[{'enabled':0}] and not db('SELECT * FROM ci_appointments'))
    fields=form_data(soup(owner.get(settings)).select_one('[data-appointment-settings]'));fields.update(timezone='UTC',slot_minutes='30',buffer_minutes='15',notice_minutes='0',enabled='1',current_password=OWNER)
    for day in range(7):fields.update({f'hours[{day}][enabled]':'1',f'hours[{day}][start]':'00:00',f'hours[{day}][end]':'24:00'})
    invalid=fields.copy();invalid['timezone']='Bad/Zone';r=owner.post(settings,data=invalid);check('Invalid availability preserves entered hours and hides password',r.status_code==200 and 'real IANA' in r.text and soup(r).select_one('[name="hours[0][end]"]')['value']=='24:00' and soup(r).select_one('[name=current_password]')['value']=='' and db('SELECT revision FROM ci_appointment_settings')==[{'revision':1}])
    r=owner.post(settings,data=fields);check('Owner explicitly enables configured public slots','Availability saved' in r.text and db('SELECT enabled,revision FROM ci_appointment_settings')==[{'enabled':1,'revision':2}])
    r=owner.post(settings,data=fields);check('Stale configuration keeps old submitted version','Availability changed' in r.text and soup(r).select_one('[name=revision]')['value']=='1' and db('SELECT revision FROM ci_appointment_settings')==[{'revision':2}])
    member_id=db("SELECT id FROM ci_users WHERE email='request-staff@example.invalid'")[0]['id'];original=db('SELECT permissions FROM ci_staff_profiles WHERE user_id=?',[member_id])[0]['permissions'];member=requests.Session();submit(member,root+'?view=login','login',{'email':'request-staff@example.invalid','password':STAFF})
    check('Staff without website permission cannot see appointments',member.get(root+'?view=consultations').status_code==403);db('UPDATE ci_staff_profiles SET permissions=? WHERE user_id=?',[json.dumps(json.loads(original)+['website.manage']),member_id]);check('Website staff can see queue but not owner settings',member.get(root+'?view=consultations').status_code==200 and member.get(settings).status_code==403)
    prospect=requests.Session();r=prospect.get(public);parsed=soup(r);slots=[int(o['value']) for o in parsed.select('[name=slot] option[value]') if o['value'] and int(o['value'])>time.time()+86400];chosen=slots[0]
    check('Configured public form shows explicit timezone without private contacts',parsed.select_one('[name=preferred_date]') is None and '(UTC+00:00)' in r.text and parsed.select_one('[name=calendar_revision]')['value']=='2' and 'request-staff@example.invalid' not in r.text)
    data=form_data(parsed.select_one('[data-growth-form]'));data.update(slot=str(chosen),timezone='America/Chicago',name='<img src=x onerror=alert(1)> Prospect',email='appointment-http@example.invalid',message='Please arrange this synthetic project consultation.',consent='1');time.sleep(2.1);r=prospect.post(public,data=data,headers={'Accept':'application/json'});check('HTTP slot submission stays pending',r.status_code==200 and r.json()['ok'] and 'not a confirmed booking' in r.json()['result']['message'])
    lead=db("SELECT id FROM ci_leads WHERE email='appointment-http@example.invalid'")[0]['id'];detail=root+'?view=consultation&id='+str(lead);saved=db('SELECT * FROM ci_appointments WHERE lead_id=?',[lead])[0];reference=r.json()['result']['reference'];r=prospect.post(public,data=data,headers={'Accept':'application/json'});check('HTTP appointment replay remains one record',r.json()['result']['reference']==reference and len(db('SELECT id FROM ci_appointments WHERE lead_id=?',[lead]))==1)
    r=owner.get(detail);check('Private appointment contact text is escaped','&lt;img' in r.text and soup(r).select_one('img[src=x]') is None and 'Pending confirmation' in r.text)
    r=submit(owner,detail,'appointments_confirm',{'current_password':'incorrect'});check('HTTP confirmation rejects wrong password and never refills it','current password' in r.text.lower() and soup(r).select_one('[name=current_password]')['value']=='' and db('SELECT status FROM ci_appointments WHERE lead_id=?',[lead])==[{'status':'requested'}])
    stale=form_data(soup(owner.get(detail)).select_one('[data-appointment-confirm]'));r=submit(owner,detail,'appointments_confirm',{'current_password':OWNER});check('Authorized staff decision confirms without sending','Confirmed' in r.text and 'no confirmation or cancellation message was sent' in r.text and db('SELECT status,revision FROM ci_appointments WHERE lead_id=?',[lead])==[{'status':'confirmed','revision':2}])
    stale['current_password']=OWNER;r=owner.post(detail,data=stale);check('Stale appointment submission cannot overwrite decision','appointment changed' in r.text and db('SELECT revision FROM ci_appointments WHERE lead_id=?',[lead])==[{'revision':2}])
    r=submit(owner,detail,'appointments_reschedule',{'slot':str(chosen+3600),'timezone':'Europe/London'});check('HTTP reschedule returns to pending with history',db('SELECT status,revision,starts_at FROM ci_appointments WHERE lead_id=?',[lead])==[{'status':'requested','revision':3,'starts_at':chosen+3600}] and len(db('SELECT id FROM ci_appointment_revisions WHERE appointment_id=?',[saved['id']]))==3)
    r=submit(owner,detail,'appointments_cancel');check('HTTP cancellation releases time and closes controls','Cancelled' in r.text and soup(r).select_one('[data-appointment-reschedule]') is None)
    db('UPDATE ci_staff_profiles SET permissions=? WHERE user_id=?',[original,member_id]);check('Current revocation immediately hides private appointment',member.get(detail).status_code==403)
    for path in ['app/marketing/appointments.php','app/marketing/appointment_content.php','database/schema/appointments_schema.php','database/migrations/appointments_migrate.php','admin/controllers/appointments.php','admin/views/appointment.php','admin/views/appointment_settings.php','pages/contact/appointment_fields.php','includes/foundation/scheduling/Consultation.php']:
        check('Appointment internal HTTP denial '+path,requests.get(BASE+'/existing/'+path).status_code==404)
    context=browser.new_context(viewport={'width':1440,'height':1000});page=context.new_page();errors=[];page.on('pageerror',lambda e:errors.append(str(e)))
    def capture(name):
        page.evaluate("document.activeElement?.blur(); window.scrollTo({top:0,behavior:'instant'})")
        page.wait_for_timeout(250)
        page.screenshot(path=str(QA/name),full_page=True)
    page.goto(public);page.locator('[name=slot]').select_option(str(chosen+7200));page.locator('[name=timezone]').select_option('America/Chicago');page.locator('[name=name]').fill('Browser consultation prospect');page.locator('[name=email]').fill('appointment-browser@example.invalid');page.locator('[name=message]').fill('Please arrange this synthetic browser consultation.');page.locator('[name=consent]').check();capture('Consultation-Public-Desktop.png');page.set_viewport_size({'width':390,'height':844});capture('Consultation-Public-Mobile.png');check('Public consultation form fits mobile',page.evaluate('document.documentElement.scrollWidth <= innerWidth'));page.wait_for_timeout(2100);page.get_by_role('button',name='Send my request').click();expect(page.locator('[data-growth-success]')).to_be_visible()
    bid=db("SELECT id FROM ci_leads WHERE email='appointment-browser@example.invalid'")[0]['id'];url=root+'?view=consultation&id='+str(bid);page.set_viewport_size({'width':1440,'height':1000});page.goto(root+'?view=login');page.locator('[name=email]').fill('owner@example.invalid');page.locator('[name=password]').fill(OWNER);page.locator('form button').first.click();page.wait_for_url(root+'?view=dashboard');page.goto(url);page.locator('[data-appointment-confirm] [name=current_password]').fill(OWNER);page.get_by_role('button',name='Confirm appointment record').click();expect(page.get_by_role('heading',name='Confirmed',exact=True)).to_be_visible();page.locator('[data-appointment-reschedule] [name=slot]').select_option(str(chosen+10800));page.get_by_role('button',name='Save new pending time').click();expect(page.get_by_role('heading',name='Pending confirmation',exact=True)).to_be_visible();capture('Consultation-Admin-Desktop.png');page.set_viewport_size({'width':390,'height':844});expect(page.locator('.admin-sidebar')).not_to_be_in_viewport();capture('Consultation-Admin-Mobile.png')
    check('Chromium confirmation and reschedule retain pending revision history',db('SELECT status,revision FROM ci_appointments WHERE lead_id=?',[bid])==[{'status':'requested','revision':3}]);check('Appointment admin fits mobile',page.evaluate('document.documentElement.scrollWidth <= innerWidth'));check('Consultation workflow has no browser errors',not errors);context.close()
